 places:[
 travelPlace('museum','重庆中国三峡博物馆','认识入口','3–4小时','用巴渝、三峡、城市与近代记忆等线索建立框架，别把重庆的来路只缩成网络景观。','选一份地图与一个普通人的生活材料，记录它们讲的是哪个时段。','当天开放的常设、临展分别看；不承诺全部展厅都开。',['cqm']),
 travelPlace('guild','湖广会馆','核心地标','2–3小时','会馆是迁民、商业组织和信仰活动的结合，帮助理解“人从哪里来，如何安顿”。','看展签里的籍贯、行会与建筑用途，找一项互助或组织功能。','历史建筑与后续保护展示分清；表演不是固定保证。',['cqGuild','cq']),
 travelPlace('slope','山城巷 · 选一段','核心地标','1.5–2.5小时','坡地决定道路、房屋与视线，也留下被改造的城市生活片段。','画一条简短的上坡/下坡剖面；记录同一处从不同高度看的变化。','现有商业与历史遗存分别看；不进居民私密空间。',['cqPlan']),
 travelPlace('lights','解放碑—洪崖洞外观 / 江岸','当代地标','1.5–2.5小时','这里可以观察城市展示自己的一面，但今日灯光与商业造景不是整片古代建筑原样遗存。','选两个观景位置，记录江、桥与建筑的关系；写一条事实而不是“魔幻”形容词。','不必挤进内部商业；高峰选外围，返程路线先查。',['cq','cqPlan']),
 travelPlace('south','龙门浩 / 南岸江边','生活现场','半天','跨江能换一个角度看港口城市、坡地与改造街区，也提醒人注意岸线和交通。','在实际说明里找一处旧用途，再比较今日使用；不是凭建筑外观猜年代。','跨江粗留45–90分钟；只选一小片区，不把全南岸步行。',['cqPlan']),
 travelPlace('ciqikou','磁器口','有余力支线','半天','作为传统街区与当代旅游商业的叠合来观察，不把每家仿古店当成历史证据。','找一段有官方说明的街巷，比较外观、旧用途与今日人流。','与南岸二选一即可；不再同时加李子坝、远郊大足或武隆。',['cqPlan'],true)
 ],
 itinerary:[travelDay('第1天 · 先读城市，再试走坡地',['museum','slope'],'上午看馆，午后休息，再选一段山城巷。','两片区之间粗留40–70分钟，坡路额外留体力。'),travelDay('第2天 · 迁民组织与两江夜景',['guild','lights'],'会馆半天，下午休息；傍晚短看江岸，不追所有灯光点。','步行前看高差，路口或出入口变化以现场为准。'),travelDay('第3天 · 换一岸看城',['south'],'南岸半天至大半天；也可替换为磁器口，不要求两处都到。','跨江是当天单独一段交通；不用反复折返。')],
